add_action( 'woocommerce_checkout_update_order_review', 'perfectpixel_retain_checkout_store' );
add_filter( 'woocommerce_checkout_get_value', 'perfectpixel_retain_checkout_value', 20, 2 );
add_filter( 'woocommerce_ship_to_different_address_checked', 'perfectpixel_retain_ship_to_different' );
add_action( 'woocommerce_checkout_order_processed', 'perfectpixel_retain_checkout_clear' );

function perfectpixel_retain_checkout_store( $posted ) {
	if ( ! WC()->session ) {
		return;
	}
	parse_str( (string) $posted, $data );

	$keep = array();
	foreach ( $data as $key => $value ) {
		if ( is_string( $value ) && preg_match( '/^(billing_|shipping_|order_|account_username$)/', $key ) ) {
			$keep[ $key ] = sanitize_text_field( wp_unslash( $value ) );
		}
	}
	$keep['ship_to_different_address'] = ! empty( $data['ship_to_different_address'] ) ? 1 : 0;

	WC()->session->set( 'perfectpixel_checkout_values', $keep );
}

function perfectpixel_retain_checkout_value( $value, $input ) {
	if ( null !== $value || ! function_exists( 'WC' ) || ! WC()->session ) {
		return $value;
	}
	$saved = (array) WC()->session->get( 'perfectpixel_checkout_values', array() );
	return isset( $saved[ $input ] ) && '' !== $saved[ $input ] ? $saved[ $input ] : $value;
}

function perfectpixel_retain_ship_to_different( $checked ) {
	if ( function_exists( 'WC' ) && WC()->session ) {
		$saved = (array) WC()->session->get( 'perfectpixel_checkout_values', array() );
		if ( isset( $saved['ship_to_different_address'] ) ) {
			return (bool) $saved['ship_to_different_address'];
		}
	}
	return $checked;
}

function perfectpixel_retain_checkout_clear() {
	if ( WC()->session ) {
		WC()->session->set( 'perfectpixel_checkout_values', null );
	}
}
